#!/usr/bin/env node

/**
 * Recursively bundles all OpenPBR BSDF headers into a single file
 * for consumption by the Slang compiler (via vite-slang).
 *
 * vite-slang only resolves #include directives in a single pass from the
 * root .slang file's directory, so nested includes inside OpenPBR headers
 * would fail. This script resolves them all and produces one self-contained file.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OPENPBR_ROOT = path.resolve(__dirname, '../third_party/openpbr-bsdf');
const OUTPUT_PATH = path.resolve(__dirname, '../src/shaders/generated/openpbr_all.h');

const included = new Set();

function resolveIncludes(filePath) {
	if (included.has(filePath)) {
		return `// [already included: ${path.relative(OPENPBR_ROOT, filePath)}]\n`;
	}
	included.add(filePath);

	let content = fs.readFileSync(filePath, 'utf8');
	const dir = path.dirname(filePath);

	// Strip include guards (#ifndef / #define / #endif pairs)
	// We keep the content between them but remove the guard directives themselves
	content = content.replace(/^#ifndef\s+\w+\s*\n#define\s+\w+\s*\n/m, '');
	// Remove the final #endif that closes the include guard
	content = content.replace(/\n#endif\s*\/\/.*$/, '');
	content = content.replace(/\n#endif\s*$/, '');

	// Recursively resolve #include directives
	const INCLUDE_REGEX = /^(\s*)#include\s+"([^"]+)"/gm;
	content = content.replace(INCLUDE_REGEX, (match, indent, specifier) => {
		const includePath = path.resolve(dir, specifier);
		if (!fs.existsSync(includePath)) {
			console.warn(`Warning: Cannot resolve #include "${specifier}" from ${filePath}`);
			return match; // Leave unresolved
		}
		const relativeName = path.relative(OPENPBR_ROOT, includePath);
		return `// ---- begin: ${relativeName} ----\n${resolveIncludes(includePath)}\n// ---- end: ${relativeName} ----`;
	});

	return content;
}

// Start from openpbr.h
const entryFile = path.join(OPENPBR_ROOT, 'openpbr.h');

let output = `// =============================================================================
// OpenPBR BSDF - Auto-generated bundled header for Slang/WGSL compilation
// Generated by scripts/bundle-openpbr.js
// Source: third_party/openpbr-bsdf/
// DO NOT EDIT - regenerate with: node scripts/bundle-openpbr.js
// =============================================================================

// Force Slang language target
#define OPENPBR_LANGUAGE_TARGET_SLANG 1

`;

output += resolveIncludes(entryFile);

// Ensure output directory exists
fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
fs.writeFileSync(OUTPUT_PATH, output, 'utf8');

const sizeKB = (Buffer.byteLength(output, 'utf8') / 1024).toFixed(1);
console.log(`Bundled OpenPBR headers → ${path.relative(process.cwd(), OUTPUT_PATH)} (${sizeKB} KB)`);
console.log(`Resolved ${included.size} files`);
